import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`solopreneur-plan`,heroTitle:`Build your solo business plan in minutes`,heroSubtitle:`Perplexity Computer analyzes your idea, models your unit economics, and delivers a 90-day action plan — automatically.`,inputUrlCta:`Build my plan`,inputUrlPlaceholder:`yourbusiness.com`,inputUrlPrefill:`Go to {url} and perform a deep analysis of this business, product, or idea. 1) Extract the core value proposition, target customer, and business model. 2) Research the market size, growth trends, and key industry dynamics for this niche. 3) Identify the top 5-10 direct competitors — analyze their pricing, positioning, strengths, and weaknesses. 4) Build a complete solopreneur business plan with these sections: Executive Summary, Problem & Solution, Target Market & Customer Personas, Competitive Landscape, Revenue Model & Pricing Strategy, Go-to-Market Plan (first 90 days), Lean Operating Budget, Key Metrics & Milestones, and Risk Assessment. 5) Include a realistic financial projection for Year 1 with monthly revenue estimates, expenses, and break-even analysis. 6) Deliver a one-page action plan with the 10 highest-impact tasks to launch in the next 30 days. Format everything in a clean, investor-ready document.`,heroOverlaySteps:[`Analyzing your business idea, skills, and target market`,`Modeling pricing, unit economics, and cost structure`,`Mapping acquisition channels and estimating CAC`,`Business plan with 90-day action steps — ready to execute`],generatingSteps:[`Researching your market, competitors, and target customer profile`,`Designing an agent to model pricing, unit economics, and acquisition channels`,`Configuring cost breakdowns, risk analysis, and revenue projections`,`Setting up your 90-day action plan with weekly milestones`],featureSectionTitle:`From idea to launch-ready plan`,featureCardTitles:[`Connects to your business stack`,`Outputs you can execute`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Google Docs, Trello, QuickBooks — Computer delivers your plan, financials, and action items straight into the tools you already use.`,`Core offer and positioning statement. Ideal customer profile. Pricing model with unit economics. Channel-by-channel CAC estimates. Fixed and variable cost breakdown. Risk mitigation playbook. A 90-day action plan with tasks you can start this week.`],capabilitySectionTitle:`Your strategist, on autopilot`,capabilitySectionSubtitle:`Describe your idea, step away, come back to a complete one-person business plan.`,capabilityCards:[{title:`Offer Positioning`,description:`Computer can research your market, analyze competitors, and craft a core offer with clear positioning — tailored to your skills and target customer.`},{title:`Unit Economics`,description:`Computer can model your pricing, estimate margins, and break down fixed and variable costs — so you know exactly what it takes to be profitable.`},{title:`Channel Strategy`,description:`Computer can evaluate acquisition channels for your niche, estimate CAC for each one, and rank them by effort-to-impact for a solo operator.`},{title:`Connect Your Tools`,description:`Computer can push your plan into Google Sheets, Notion, Google Docs, Trello, and more — build workflows across your entire planning stack.`},{title:`Remember & Refine`,description:`Computer can remember your business context, past plans, and pivots across sessions — so every iteration builds on what you've already learned.`},{title:`Monitor & Alert`,description:`Computer can track your 90-day milestones and flag when assumptions change — like new competitors, shifting costs, or missed deadlines.`}]});export{t as default};
